import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.distributed as dist


def _world_size():
    if dist.is_available() and dist.is_initialized():
        return dist.get_world_size()
    return 1


def _rank():
    if dist.is_available() and dist.is_initialized():
        return dist.get_rank()
    return 0


class _AllGather(torch.autograd.Function):
    """Concatenate this rank's tensor with all others along the last dim."""

    @staticmethod
    def forward(ctx, x):
        ws = _world_size()
        ctx.ws = ws
        ctx.rank = _rank()
        if ws == 1:
            return x
        x = x.contiguous()
        gathered = [torch.empty_like(x) for _ in range(ws)]
        dist.all_gather(gathered, x)
        gathered[ctx.rank] = x  # keep autograd link for local slice
        return torch.cat(gathered, dim=-1)

    @staticmethod
    def backward(ctx, grad_output):
        if ctx.ws == 1:
            return grad_output
        local = grad_output.chunk(ctx.ws, dim=-1)[ctx.rank]
        return local.contiguous()


class _AllReduce(torch.autograd.Function):
    """Sum this rank's tensor with all others (all_reduce)."""

    @staticmethod
    def forward(ctx, x):
        if _world_size() == 1:
            return x
        y = x.clone()
        dist.all_reduce(y)
        return y

    @staticmethod
    def backward(ctx, grad_output):
        return grad_output


class ColumnParallelLinear(torch.nn.Module):
    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        ws = _world_size()
        rank = _rank()
        self.in_features = in_features
        self.out_features = out_features
        assert out_features % ws == 0, "out_features must be divisible by world_size"
        self.out_per_rank = out_features // ws

        # master_weight: [out_features, in_features]; split along dim 0 (output dim)
        w = master_weight.detach()
        shard = w[rank * self.out_per_rank:(rank + 1) * self.out_per_rank, :]
        self.weight = nn.Parameter(shard.clone())

        if bias:
            self.bias = nn.Parameter(torch.zeros(self.out_per_rank,
                                                 dtype=self.weight.dtype,
                                                 device=self.weight.device))
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        local = F.linear(x, self.weight, self.bias)
        return _AllGather.apply(local)


class RowParallelLinear(torch.nn.Module):
    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        ws = _world_size()
        rank = _rank()
        self.in_features = in_features
        self.out_features = out_features
        assert in_features % ws == 0, "in_features must be divisible by world_size"
        self.in_per_rank = in_features // ws

        # master_weight: [out_features, in_features]; split along dim 1 (input dim)
        w = master_weight.detach()
        shard = w[:, rank * self.in_per_rank:(rank + 1) * self.in_per_rank]
        self.weight = nn.Parameter(shard.clone())

        if bias:
            self.bias = nn.Parameter(torch.zeros(out_features,
                                                 dtype=self.weight.dtype,
                                                 device=self.weight.device))
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        # x is already scattered along last dim: [*, in_features/ws]
        local = F.linear(x, self.weight)
        reduced = _AllReduce.apply(local)
        if self.bias is not None:
            reduced = reduced + self.bias
        return reduced
